package com.example.lebiais.sonde

import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue

/** Au-dessous, l'image « saccade » : un échantillon dont le minimum passe sous ce seuil est un creux. */
const val SEUIL_CREUX_FPS = 20

/** Une pause entre deux images d'au moins cette durée est un gel, même si la moyenne par seconde reste haute. */
const val SEUIL_GEL_MS = 500

/** Une ligne du relevé : ce que la sonde faisait et gardait en mémoire à ce moment. */
data class Echantillon(
    val heure: String,
    val ecran: String,
    /** Images par seconde, lues à la dernière seconde pleine. */
    val fps: Int,
    /** Le pire des fps du dernier intervalle (c'est lui qui trahit une saccade). */
    val fpsMin: Int,
    val photos: Int,
    val fiches: Int,
    /** Mémoire des photos décodées, en Mo. */
    val decodesMo: Int,
    /** La plus longue pause entre deux images dans l'intervalle, en ms (page cachée exclue). */
    val geleeMs: Int = 0,
) {
    fun ligne(): String = "$heure|$ecran|$fps|$fpsMin|$photos|$fiches|$decodesMo|$geleeMs"

    companion object {
        fun lire(ligne: String): Echantillon? {
            val p = ligne.split('|')
            if (p.size != 7 && p.size != 8) return null
            return Echantillon(
                p[0], p[1],
                p[2].toIntOrNull() ?: return null,
                p[3].toIntOrNull() ?: return null,
                p[4].toIntOrNull() ?: return null,
                p[5].toIntOrNull() ?: return null,
                p[6].toIntOrNull() ?: return null,
                if (p.size == 8) (p[7].toIntOrNull() ?: return null) else 0,
            )
        }
    }
}

class ResumeDuReleve(val nombre: Int, val fpsMoyen: Int, val fpsMin: Int, val creux: List<Echantillon>, val geleeMax: Int = 0) {
    fun enTexte(derniers: Int = 10): String {
        if (nombre == 0) return "Aucun échantillon pour l'instant (un toutes les 5 s, page visible)."
        val tete = "$nombre échantillons · moyenne $fpsMoyen i/s · pire $fpsMin i/s · pause max $geleeMax ms · ${creux.size} creux (< $SEUIL_CREUX_FPS i/s ou pause ≥ $SEUIL_GEL_MS ms)"
        if (creux.isEmpty()) return tete
        val lignes = creux.takeLast(derniers).joinToString("\n") {
            "${it.heure} · ${it.ecran} · min ${it.fpsMin} i/s · pause ${it.geleeMs} ms · ${it.photos} photos (${it.decodesMo} Mo) · ${it.fiches} fiches"
        }
        return tete + "\n" + lignes
    }
}

fun resumeDuReleve(echantillons: List<Echantillon>): ResumeDuReleve {
    if (echantillons.isEmpty()) return ResumeDuReleve(0, 0, 0, emptyList())
    return ResumeDuReleve(
        nombre = echantillons.size,
        fpsMoyen = echantillons.sumOf { it.fps } / echantillons.size,
        fpsMin = echantillons.minOf { it.fpsMin },
        creux = echantillons.filter { it.fpsMin < SEUIL_CREUX_FPS || it.geleeMs >= SEUIL_GEL_MS },
        geleeMax = echantillons.maxOf { it.geleeMs },
    )
}

/** L'état vivant du suivi de fluidité, lu par le bandeau, alimenté par la boucle d'images de `Sonde()`. */
object Fluidite {
    var fps by mutableStateOf(0)
    /** Le pire fps depuis le dernier échantillon écrit. */
    var minFenetre: Int = Int.MAX_VALUE
    /** La plus longue pause entre deux images depuis le dernier échantillon écrit. */
    var geleeFenetre: Int = 0
    var ecran: String = "Menu"

    fun noter(fpsSeconde: Int) {
        fps = fpsSeconde
        if (fpsSeconde < minFenetre) minFenetre = fpsSeconde
    }

    fun noterPause(ms: Int) { if (ms > geleeFenetre) geleeFenetre = ms }

    /** Écrit un échantillon dans le relevé du navigateur (JS l'ignore si la page est cachée). */
    fun enregistrer(ecranVoulu: String = ecran) {
        val min = if (minFenetre == Int.MAX_VALUE) fps else minFenetre
        minFenetre = Int.MAX_VALUE
        val gelee = geleeFenetre
        geleeFenetre = 0
        Navigateur.releveAjouter(
            Echantillon(Navigateur.heure(), ecranVoulu, fps, min, nombrePhotos(), nombreFiches(), (octetsDecodesPhotos() / 1048576L).toInt(), gelee).ligne(),
        )
    }

    fun lire(): ResumeDuReleve = resumeDuReleve(Navigateur.releveLire().lines().mapNotNull { Echantillon.lire(it) })
}

/** Libère tout ce que la sonde garde exprès en mémoire : photos, fiches, saisies en cours. */
fun viderLesCaches() {
    viderPhotos()
    viderFiches()
    Fluidite.enregistrer("vidé")
}
